def solve_backtrack(grid, r, c, num_colors):
    rows = len(grid)
    cols = len(grid[0])
    if r == rows:
        return True

    next_r, next_c = (r, c + 1) if c < cols - 1 else (r + 1, 0)

    # Try to use a new color if possible
    # To reduce search space, we only use colors in range [1, num_colors]
