def solve_backtrack(grid, r, c, k):
    rows = len(grid)
    cols = len(grid[0])
    if r == rows:
        # Check if all k colors were used
        used_colors = set()
        for row in grid:
            for val in row:
                used_colors.add(val)
        return len(used_colors) == k

    next_r, next_c = (r, c + 1) if c < cols - 1 else (r + 1, 0)

    # To find if k distinct colors are possible, we can use colors 1..k
    for color in range(1, k + 1):
        grid[r][c] = color
        if check_valid(grid, r, c):
            if solve_backtrack(grid, next_r, next_c, k):
                return True
    return False

def max_distinct_colors(rows, cols):
    for k in range(rows * cols, 0, -1):
        grid = [[0]*cols for _ in range(rows)]
        if solve_backtrack(grid, 0, 0, k):
            return k
    return 0

