def local_search(rows, cols, iterations=10000):
    # Start with a random grid
    grid = [[random.randint(1, rows*cols) for _ in range(cols)] for _ in range(rows)]

    best_grid = [row[:] for row in grid]
    best_score = 0

    for i in range(iterations):
        r, c = random.randint(0, rows-1), random.randint(0, cols-1)
        old_val = grid[r][c]
        # Try a new random color
        grid[r][c] = random.randint(1, rows*cols)

